def construct():
    state0 = root()
    if complete(state0):
        return state0
    info = inspect(state0)
    rows = info.get('order_details')
    if rows is None:
        rows = []
    buckets = {}
    for row in rows:
        r = row.get('route')
        o = row.get('order')
        if r is not None and o is not None:
            if r not in buckets:
                buckets[r] = []
            buckets[r].append(o)
    routes = sorted(buckets.keys())
    if len(routes) == 0:
        return None
    for r in routes:
        buckets[r].sort()
    max_level = 0
    for r in routes:
        n = len(buckets[r])
        if n > max_level:
            max_level = n
    def build_waves(route_order, size):
        ordered = []
        for level in range(max_level):
            for r in route_order:
                if level < len(buckets[r]):
                    ordered.append(buckets[r][level])
        waves = []
        i = 0
        while i < len(ordered):
            waves.append(ordered[i:i + size])
            i = i + size
        return waves
    custom = []
    for name in ['C430', 'CFLAT', 'C280I', 'C280R']:
        if name in buckets and name not in custom:
            custom.append(name)
    for r in routes:
        if r not in custom:
            custom.append(r)
    primary = build_waves(routes, 4)
    alternate = build_waves(custom, 4)
    best_state = None
    best_score = -1
    best_policy = -1
    calls = 0
    max_calls = 6
    policies = [1, 3, 0]
    for p in policies:
        if calls >= max_calls or remaining() < 2:
            break
        calls = calls + 1
        st = batches(primary, policy=p, seed=0)
        if st is not None and complete(st):
            sc = inspect(st).get('day_busy_ticks')
            if sc is None:
                sc = 0
            sc = int(sc)
            if sc > best_score:
                best_score = sc
                best_state = st
                best_policy = p
                if best_score >= 2610:
                    return best_state
    if calls < max_calls and remaining() > 2:
        alt_policies = []
        if best_policy >= 0:
            alt_policies.append(best_policy)
        for p in [3, 0, 1]:
            if p not in alt_policies:
                alt_policies.append(p)
        for p in alt_policies:
            if calls >= max_calls or remaining() <= 2:
                break
            calls = calls + 1
            st = batches(alternate, policy=p, seed=0)
            if st is not None and complete(st):
                sc = inspect(st).get('day_busy_ticks')
                if sc is None:
                    sc = 0
                sc = int(sc)
                if sc > best_score:
                    best_score = sc
                    best_state = st
                    best_policy = p
                    if best_score >= 2610:
                        return best_state
    if best_state is not None and best_policy >= 0 and calls < max_calls and remaining() > 2:
        for seed in [1, 2]:
            if calls >= max_calls or remaining() <= 2:
                break
            calls = calls + 1
            st = batches(primary, policy=best_policy, seed=seed)
            if st is not None and complete(st):
                sc = inspect(st).get('day_busy_ticks')
                if sc is None:
                    sc = 0
                sc = int(sc)
                if sc > best_score:
                    best_score = sc
                    best_state = st
                    if best_score >= 2610:
                        return best_state
    return best_state
